import{c as e,t}from"./jsx-runtime-DpMzcJ0U.js";import{_ as n}from"./shared-C2aP1qIa.js";import{n as r,r as i,t as a}from"./shared-rrg0QpfD.js";var o=t();function s(){let t=e();return(0,o.jsxs)(`div`,{style:{display:`flex`,flexDirection:`column`,minHeight:`100dvh`,background:`var(--dark-bg-canvas)`,fontFamily:`var(--font-body)`},children:[(0,o.jsx)(n,{onBack:()=>t(-1),title:`Privacy Policy`,tone:`dark`}),(0,o.jsxs)(`div`,{style:{padding:`24px 20px 40px`,flex:1,display:`flex`,flexDirection:`column`,gap:20},children:[(0,o.jsx)(`div`,{style:{fontSize:13,color:`var(--dark-text-faint)`},children:`Last updated: August 27, 2026`}),(0,o.jsxs)(`div`,{style:{fontSize:14,color:`var(--dark-text-muted)`,lineHeight:1.65},children:[`Kairo is a UTME exam-prep app built by Techmed Integrated Services ("TechMed"). This policy explains what information we collect when you use Kairo, why we collect it, and what choices you have. It covers Kairo at`,` `,(0,o.jsx)(a,{href:`https://kairo.techmedng.com`,children:`kairo.techmedng.com`}),` — not TechMed's other products, except where noted below.`]}),(0,o.jsxs)(i,{heading:`1. Information We Collect`,children:[(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`strong`,{style:{color:`var(--dark-text-heading)`},children:`Account information.`}),` When you create a Kairo account, you give us your name, email address, and a password — or sign in with Google, in which case Google shares your name and email with us. We never see or store your password in plain text; Supabase, our authentication provider, holds it in encrypted form only.`]}),(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`strong`,{style:{color:`var(--dark-text-heading)`},children:`Your study profile.`}),` To personalize Kairo, we ask for your target UTME exam date, the course you're aiming for, and the subjects you're preparing. You can optionally add your target university, target UTME score, and preferred study times — none of that is required to use Kairo.`]}),(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`strong`,{style:{color:`var(--dark-text-heading)`},children:`Your learning activity.`}),` As you use Practice, CBT mock exams, Rapid Fire, and the Study Planner, we record what you answered, whether you got it right, how long you took, your streaks, badges, Kairo Points, and your mastery of each topic. This is the core of how Kairo adapts to you — without it, Kairo can't recommend what to study next.`]}),(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`strong`,{style:{color:`var(--dark-text-heading)`},children:`Notifications.`}),` If you turn on push notifications, your browser gives us a subscription address (a routing address, not a readable message) so we can send reminders. We also keep a record of which notification categories you've enabled and a short history of what's been sent to you.`]}),(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`strong`,{style:{color:`var(--dark-text-heading)`},children:`Feedback you send us.`}),` If you report a problem with a question or send us feedback, we store what you wrote so it can be reviewed and acted on.`]}),(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`strong`,{style:{color:`var(--dark-text-heading)`},children:`Basic technical information.`}),` Your browser identifies itself (e.g. "Chrome on Android") so push notifications can be delivered correctly. We don't use this to track you across other sites.`]})]}),(0,o.jsx)(i,{heading:`2. What We Don't Collect`,children:(0,o.jsx)(r,{items:[`No third-party analytics, advertising, or tracking scripts run on Kairo — no Google Analytics, no ad pixels, no cross-site trackers.`,`No tracking cookies. The only things stored in your browser are functional — your sign-in session, an in-progress practice/CBT session so you can resume it, and today’s recommended focus topic. None of it is shared with third parties or used to track you elsewhere.`,`No payment information — Kairo is currently free, so there's nothing to collect. If that changes, we'll update this policy and tell you directly before asking you to pay for anything.`,`No age, date of birth, or parent/guardian contact — Kairo doesn't currently ask for or verify these. See “Children & Minors” below for what that means in practice.`]})}),(0,o.jsxs)(i,{heading:`3. How We Use Your Information`,children:[(0,o.jsx)(r,{items:[`To run Kairo: serve the right practice questions, track your progress, run your streak and points, and build your Study Planner.`,`To communicate with you: exam-date reminders and streak nudges you've opted into, plus essential account emails like verifying your address or resetting your password.`,`To improve Kairo: understanding, in aggregate, where students struggle helps us fix bad questions and build better content — we don’t need your name to see that a question confuses a lot of people.`,`To keep your account secure and respond to bugs or abuse you report.`]}),(0,o.jsx)(`div`,{children:`We do not sell your information to anyone, for any reason.`})]}),(0,o.jsxs)(i,{heading:`4. Who We Share Information With`,children:[(0,o.jsx)(`div`,{children:`We use a small number of service providers to run Kairo, and only share what each one needs to do its job:`}),(0,o.jsx)(r,{items:[`Supabase — hosts our database and handles sign-in. Your account and study data live here, protected by row-level security rules that only ever let your signed-in account read your own data.`,`Resend — delivers the transactional emails Kairo sends (verification, password reset, reminders).`,`Cloudflare — hosts the Kairo app itself.`,`Your browser's own push service (run by Google, Mozilla, or Apple, depending on your browser) — how any web app's push notifications reach your device.`]}),(0,o.jsx)(`div`,{children:`None of these providers may use your data for their own purposes.`}),(0,o.jsx)(`div`,{children:`One thing worth knowing: Kairo shares its sign-in system with other TechMed products (including a legacy product, RoboMed). Your email and password authenticate you across TechMed's products through one shared identity system — but your Kairo study data (answers, progress, streaks, profile) lives in Kairo's own database and isn't used by or shared with those other products.`})]}),(0,o.jsx)(i,{heading:`5. How Long We Keep Your Information`,children:(0,o.jsx)(`div`,{children:`We keep your account and study data for as long as your account is active, so your progress and history stay intact. If you ask us to delete your account, we delete your personal information, other than what we're required to retain for legal or security reasons (like a record that a deletion happened).`})}),(0,o.jsx)(i,{heading:`6. Your Choices`,children:(0,o.jsx)(r,{items:[`Update your profile — your exam date, target course, subjects, university, and target score are editable anytime from Edit Profile.`,`Control notifications — turn channels and categories on or off anytime from Notification Settings.`,(0,o.jsxs)(o.Fragment,{children:[`Delete your account or request a copy of your data — Kairo doesn't yet have a self-service button for this. Until it does, email `,(0,o.jsx)(a,{href:`mailto:privacy@techmedng.com`,children:`privacy@techmedng.com`}),` and we'll handle it directly, typically within 30 days.`]})]})}),(0,o.jsx)(i,{heading:`7. Children & Minors`,children:(0,o.jsxs)(`div`,{children:[`Many Kairo students preparing for UTME are teenagers, often under 18. Kairo doesn't currently ask for or verify anyone's age, and there's no separate parental-consent flow. If you're a parent or guardian and believe your child has created a Kairo account and you'd like to review, adjust, or delete their information, contact us at `,(0,o.jsx)(a,{href:`mailto:privacy@techmedng.com`,children:`privacy@techmedng.com`}),` and we'll work with you directly.`]})}),(0,o.jsx)(i,{heading:`8. Security`,children:(0,o.jsx)(`div`,{children:`We rely on Supabase's encrypted infrastructure and enforce row-level security so your data is only ever readable by your own signed-in account. All traffic between your device and Kairo is encrypted (HTTPS). No system is perfectly secure, but we take reasonable, industry-standard steps to protect your information.`})}),(0,o.jsx)(i,{heading:`9. Changes to This Policy`,children:(0,o.jsx)(`div`,{children:`If we materially change how we handle your information, we'll update this page and the "Last updated" date above. For significant changes, we'll also try to notify you directly — by email or in-app.`})}),(0,o.jsxs)(`div`,{style:{display:`flex`,flexDirection:`column`,gap:8,paddingTop:4},children:[(0,o.jsx)(`div`,{style:{fontFamily:`var(--font-heading)`,fontWeight:700,fontSize:16,color:`var(--dark-text-heading)`},children:`Contact Us`}),(0,o.jsxs)(`div`,{style:{fontSize:14,color:`var(--dark-text-muted)`,lineHeight:1.65},children:[`Questions about this policy or your data? Email `,(0,o.jsx)(a,{href:`mailto:privacy@techmedng.com`,children:`privacy@techmedng.com`}),`.`]}),(0,o.jsx)(`div`,{style:{fontSize:12,color:`var(--dark-text-faint)`,marginTop:6},children:`Techmed Integrated Services, operator of Kairo — kairo.techmedng.com. This policy is governed by the laws of the Federal Republic of Nigeria.`})]})]})]})}export{s as PrivacyPage};